import{_ as i,o as e,c as l,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"研究方向","description":"","frontmatter":{},"headers":[],"relativePath":"research/index.md","filePath":"research/index.md"}'),t={name:"research/index.md"};function h(n,a,c,o,p,s){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="研究方向" tabindex="-1">研究方向 <a class="header-anchor" href="#研究方向" aria-label="Permalink to &quot;研究方向&quot;">​</a></h1><p>多学科仿真智能课题组围绕计算机、数学与工程领域开展交叉研究， 重点关注复杂工程问题中的数学建模、科学计算、数值仿真与人工智能方法。</p><h2 id="多物理场仿真" tabindex="-1">多物理场仿真 <a class="header-anchor" href="#多物理场仿真" aria-label="Permalink to &quot;多物理场仿真&quot;">​</a></h2><p>研究复杂物理系统的数学建模、数值离散、高性能求解与可视化。</p><p>主要研究内容：</p><ul><li>多物理场耦合</li><li>有限元与数值仿真</li><li>工程仿真软件</li><li>高性能计算</li><li>模型降阶</li></ul><p><a href="/research/multiphysics.html">了解更多 →</a></p><h2 id="科学计算" tabindex="-1">科学计算 <a class="header-anchor" href="#科学计算" aria-label="Permalink to &quot;科学计算&quot;">​</a></h2><p>研究数学模型的高效数值求解方法及其工程应用。</p><p>主要研究内容：</p><ul><li>数值分析</li><li>线性与非线性方程组</li><li>高性能计算</li><li>科学计算库</li><li>数值优化</li></ul><p><a href="/research/scientific-computing.html">了解更多 →</a></p><h2 id="人工智能" tabindex="-1">人工智能 <a class="header-anchor" href="#人工智能" aria-label="Permalink to &quot;人工智能&quot;">​</a></h2><p>探索人工智能与科学计算、工程仿真之间的交叉融合。</p><p>主要研究内容：</p><ul><li>科学机器学习</li><li>AI for Science</li><li>智能优化</li><li>数据驱动建模</li><li>大模型与智能计算</li></ul><p><a href="/research/artificial-intelligence.html">了解更多 →</a></p><h2 id="化工过程与系统" tabindex="-1">化工过程与系统 <a class="header-anchor" href="#化工过程与系统" aria-label="Permalink to &quot;化工过程与系统&quot;">​</a></h2><p>面向复杂化工过程与工程系统开展建模、模拟、优化与控制研究。</p><p>主要研究内容：</p><ul><li>化工过程模拟</li><li>水处理与海水淡化</li><li>过程优化</li><li>系统建模与控制</li><li>数字孪生</li></ul><p><a href="/research/chemical-engineering.html">了解更多 →</a></p>',22)])])}const m=i(t,[["render",h]]);export{u as __pageData,m as default};
